"""Java page-object generation driven by `JavaDef`."""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path

from crawler.config import JavaDef
from crawler.model import LocatorResult

from . import naming
from .xpath import xpath_literal  # noqa: F401  (re-exported for callers/tests)

HEADER = (
    "// Generated by crawler. DO NOT EDIT BY HAND.\n"
    "// Regenerate with `crawler run`.\n"
)
GENERATED_MARKER = "// Generated by crawler. DO NOT EDIT BY HAND."
INDENT = "    "
SUPPORT_DIR = Path(__file__).parent / "support"
STYLES = ("by_constants", "findby_fields", "by_methods")
_KNOWN_TYPES = {
    "WebDriver": "org.openqa.selenium.WebDriver",
    "WebElement": "org.openqa.selenium.WebElement",
    "SearchContext": "org.openqa.selenium.SearchContext",
}


# ---------------------------------------------------------------- escaping

def java_string(s: str) -> str:
    """A Java string literal (with quotes). Non-ASCII stays as-is (files are UTF-8)."""
    out = []
    for ch in s:
        o = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif o < 0x20 or o == 0x7F or 0xD800 <= o <= 0xDFFF:
            # \\uXXXX is pre-lexing in Java, but every char except CR/LF (handled above) is legal in a literal.
            out.append(f"\\u{o:04x}")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def javadoc_text(s: str) -> str:
    """Make arbitrary text safe inside a /** ... */ comment (and as HTML)."""
    s = s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    s = s.replace("@", "&#64;").replace("\\", "&#92;")  # tags / {@...}; \\u escapes are pre-lexing
    s = s.replace("*/", "*&#47;").replace("/*", "&#47;*")
    s = re.sub(r"[\r\n  \x00-\x1f]+", " ", s)
    return s


def fmt_score(score: float) -> str:
    return f"{float(score):.2f}".rstrip("0").rstrip(".")


# ---------------------------------------------------------------- model

@dataclass
class Member:
    result: LocatorResult
    ident: str
    params: list[tuple[str, str]] = field(default_factory=list)  # (template param, java identifier)


@dataclass
class PageClass:
    name: str
    pages: list[str]
    elements: list[Member]
    templates: list[Member]
    ctor_field: str | None = None


def _ctor_arg(java: JavaDef) -> tuple[str, str] | None:
    """("WebDriver", "driver") from "WebDriver driver" / "final WebDriver driver"."""
    if not java.constructor_arg or not java.constructor_arg.strip():
        return None
    parts = java.constructor_arg.replace("final ", " ").split()
    if len(parts) < 2:
        return parts[0], "driver"
    return " ".join(parts[:-1]), parts[-1]


def _simple(fqcn: str) -> str:
    return fqcn.rsplit(".", 1)[-1]


def _pkg(fqcn: str) -> str:
    return fqcn.rsplit(".", 1)[0] if "." in fqcn else ""


def plan_classes(results: list[LocatorResult], java: JavaDef, taken_classes: set[str] = frozenset()) -> list[PageClass]:
    """Group results into classes and assign unique Java identifiers, deterministically."""
    if java.locator_style not in STYLES:
        raise ValueError(f"java.locator_style must be one of {STYLES}, got {java.locator_style!r}")
    groups: dict[str, list[LocatorResult]] = {}
    for r in results:
        cname = naming.class_name(r.page, java.class_suffix)
        if cname in taken_classes:
            cname += "_"
        groups.setdefault(cname, []).append(r)

    ctor = _ctor_arg(java)
    upper = java.locator_style == "by_constants" and java.constant_case.upper() != "CAMEL"
    out = []
    for cname in sorted(groups):
        rs = sorted(groups[cname], key=_sort_key)
        reserved = {cname}
        ctor_field = None
        if ctor and not java.base_class and java.locator_style != "findby_fields":
            ctor_field = ctor[1]
        if ctor:
            reserved.add(ctor[1])
        ns = naming.Namespace(reserved)
        elements, templates = [], []
        for r in rs:
            if r.template is not None:
                ident = ns.take(naming.camel(r.name))
                pns = naming.Namespace()
                params = [(p, pns.take(naming.camel(p, "value"))) for p in r.template.params]
                templates.append(Member(r, ident, params))
            else:
                base = naming.upper_snake(r.name) if upper else naming.camel(r.name)
                elements.append(Member(r, ns.take(base, upper=upper)))
        out.append(PageClass(cname, sorted({r.page for r in rs}), elements, templates, ctor_field))
    return out


def _sort_key(r: LocatorResult):
    return (r.name, r.page, r.xpath, r.strategy, r.template is not None)


# ---------------------------------------------------------------- rendering

def _javadoc(r: LocatorResult, indent: str) -> list[str]:
    lines = []
    lines.append(javadoc_text(f"{r.name}: {r.strategy}, score {fmt_score(r.score)}, verified in {r.runs_verified} run(s)")
                 + (f", element &lt;{javadoc_text(r.tag)}&gt;" if r.tag else "") + ".")
    if r.fragile:
        reason = "; ".join(r.notes) if r.notes else "no reason recorded"
        lines.append("<p>FRAGILE: " + javadoc_text(reason) + "</p>")
    elif r.notes:
        lines.append("<p>Notes: " + javadoc_text("; ".join(r.notes)) + "</p>")
    if r.template is not None:
        lines.append("<p>Template: <code>" + javadoc_text(r.template.xpath) + "</code></p>")
        if r.template.example:
            ex = ", ".join(f"{k}={v!r}" for k, v in sorted(r.template.example.items()))
            lines.append("<p>Example: " + javadoc_text(ex) + " gives <code>" + javadoc_text(r.xpath) + "</code></p>")
    if r.fallbacks:
        lines.append("<p>Fallbacks:</p>")
        lines.append("<ul>")
        for c in r.fallbacks:
            lines.append(f"<li><code>{javadoc_text(c.xpath)}</code> ({javadoc_text(c.strategy)}, {fmt_score(c.score)})</li>")
        lines.append("</ul>")
    if r.sources:
        lines.append("<p>Sources: " + javadoc_text(", ".join(sorted(set(r.sources)))) + "</p>")
    body = [indent + "/**"] + [indent + " * " + ln for ln in lines] + [indent + " */"]
    return body


def _template_expr(m: Member) -> str:
    t = m.result.template
    idents = dict(m.params)
    if not idents:
        return java_string(t.xpath)
    pattern = re.compile(r"\{(" + "|".join(re.escape(p) for p in sorted(idents, key=len, reverse=True)) + r")\}")
    parts: list[str] = []
    pos = 0
    for mt in pattern.finditer(t.xpath):
        if mt.start() > pos:
            parts.append(java_string(t.xpath[pos:mt.start()]))
        parts.append(f"XPathLiteral.of({idents[mt.group(1)]})")
        pos = mt.end()
    if pos < len(t.xpath):
        parts.append(java_string(t.xpath[pos:]))
    if not parts:
        return '""'
    return " + ".join(parts)


def _imports(pc: PageClass, java: JavaDef, helper_pkg: str) -> list[str]:
    imps = {"org.openqa.selenium.By"}
    style = java.locator_style
    ctor = _ctor_arg(java)
    if style == "findby_fields" and pc.elements:
        imps |= {"org.openqa.selenium.WebElement", "org.openqa.selenium.support.FindBy"}
    if style == "findby_fields" and not java.base_class:
        imps.add("org.openqa.selenium.support.PageFactory")
    needs_ctor = _needs_ctor(java)
    if needs_ctor:
        typ = ctor[0] if ctor else "WebDriver"
        if typ in _KNOWN_TYPES:
            imps.add(_KNOWN_TYPES[typ])
    if java.base_class and _pkg(java.base_class) and _pkg(java.base_class) != java.package:
        imps.add(java.base_class)
    if pc.templates and helper_pkg != java.package:
        imps.add(f"{helper_pkg}.XPathLiteral")
    lines = {f"import {i};" for i in imps}
    for raw in java.imports or []:
        s = raw.strip().rstrip(";").strip()
        if s.startswith("import "):
            s = s[len("import "):].strip()
        if s:
            lines.add(f"import {s};")
    normal = sorted(x for x in lines if not x.startswith("import static "))
    static = sorted(x for x in lines if x.startswith("import static "))
    return normal + ([""] + static if static and normal else static)


def _needs_ctor(java: JavaDef) -> bool:
    if java.constructor_arg and java.constructor_arg.strip():
        return True
    return java.locator_style == "findby_fields" and not java.base_class


def render_class(pc: PageClass, java: JavaDef, helper_pkg: str) -> str:
    style = java.locator_style
    ctor = _ctor_arg(java)
    if ctor is None and _needs_ctor(java):
        ctor = ("WebDriver", "driver")
    I = INDENT
    out: list[str] = [HEADER.rstrip("\n"), f"package {java.package};", ""]
    imps = _imports(pc, java, helper_pkg)
    if imps:
        out += imps + [""]
    pages = ", ".join(pc.pages)
    out += ["/**", f" * Page object for {javadoc_text(pages)}.", " * Generated by crawler; do not edit by hand. Regenerate with <code>crawler run</code>.", " */"]
    ext = f" extends {_simple(java.base_class)}" if java.base_class else ""
    out.append(f"public class {pc.name}{ext} {{")

    body: list[list[str]] = []
    if pc.ctor_field:
        body.append([f"{I}protected final {ctor[0]} {ctor[1]};"])
    for m in pc.elements:
        lit = java_string(m.result.xpath)
        doc = _javadoc(m.result, I)
        if style == "by_constants":
            body.append(doc + [f"{I}public static final By {m.ident} = By.xpath({lit});"])
        elif style == "findby_fields":
            body.append(doc + [f"{I}@FindBy(xpath = {lit})", f"{I}private WebElement {m.ident};"])
    if ctor:
        lines = [f"{I}public {pc.name}({ctor[0]} {ctor[1]}) {{"]
        if java.base_class:
            lines.append(f"{I}{I}super({ctor[1]});")
        elif style == "findby_fields":
            lines.append(f"{I}{I}PageFactory.initElements({ctor[1]}, this);")
        elif pc.ctor_field:
            lines.append(f"{I}{I}this.{ctor[1]} = {ctor[1]};")
        lines.append(f"{I}}}")
        body.append(lines)
    if style == "by_methods":
        for m in pc.elements:
            body.append(_javadoc(m.result, I) + [
                f"{I}public By {m.ident}() {{",
                f"{I}{I}return By.xpath({java_string(m.result.xpath)});",
                f"{I}}}",
            ])
    for m in pc.templates:
        sig = ", ".join(f"String {ident}" for _, ident in m.params)
        body.append(_javadoc(m.result, I) + [
            f"{I}public static By {m.ident}({sig}) {{",
            f"{I}{I}return By.xpath({_template_expr(m)});",
            f"{I}}}",
        ])
    for block in body:
        out.append("")
        out += block
    out.append("}")
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------- support files

XPATH_LITERAL_JAVA = """\
package __PACKAGE__;

/**
 * Builds XPath 1.0 string literals: {@code 'x'}, {@code "x"} or {@code concat(...)} when the
 * value contains both quote kinds. Mirrors {@code crawler.emit.xpath.xpath_literal} in Python.
 */
public final class XPathLiteral {
    private XPathLiteral() {
    }

    public static String of(String value) {
        if (value == null) {
            throw new IllegalArgumentException("XPath literal value must not be null");
        }
        if (value.indexOf('\\'') < 0) {
            return "'" + value + "'";
        }
        if (value.indexOf('"') < 0) {
            return "\\"" + value + "\\"";
        }
        StringBuilder sb = new StringBuilder("concat(");
        String[] parts = value.split("'", -1);
        boolean first = true;
        for (int i = 0; i < parts.length; i++) {
            if (i > 0) {
                if (!first) {
                    sb.append(", ");
                }
                sb.append("\\"'\\"");
                first = false;
            }
            if (!parts[i].isEmpty()) {
                if (!first) {
                    sb.append(", ");
                }
                sb.append('\\'').append(parts[i]).append('\\'');
                first = false;
            }
        }
        return sb.append(')').toString();
    }
}
"""

_PKG_LINE = re.compile(r"^[ \t]*package[ \t]+(?:__PACKAGE__|[\w.]+)[ \t]*;[ \t]*$", re.M)


def support_sources(helper_pkg: str) -> dict[str, str]:
    """{file name: Java source} for XPathLiteral plus every crawler/emit/support/*.java."""
    files = {"XPathLiteral.java": XPATH_LITERAL_JAVA}
    if SUPPORT_DIR.is_dir():
        for p in sorted(SUPPORT_DIR.glob("*.java")):
            if p.name == "XPathLiteral.java":
                continue  # the generated helper is authoritative
            files[p.name] = p.read_text(encoding="utf-8")
    out = {}
    for name, src in files.items():
        src = src.replace("\r\n", "\n")
        if _PKG_LINE.search(src):
            src = _PKG_LINE.sub(f"package {helper_pkg};", src, count=1)
        else:
            src = f"package {helper_pkg};\n\n" + src
        if GENERATED_MARKER not in src:
            src = HEADER + src
        out[name] = src if src.endswith("\n") else src + "\n"
    return out
